input.newString:
ctx.save();
ctx.translate(ship.x, ship.y);
ctx.rotate(ship.angle);
// ship body
ctx.fillStyle = '#fff';
ctx.beginPath();
ctx.moveTo(ship.r, 0);
ctx.lineTo(-ship.r, ship.r * 0.6);
ctx.lineTo(-ship.r, -ship.r * 0.6);
ctx.closePath();
ctx.fill();
// ship outline
ctx.strokeStyle = '#0ff';
ctx.lineWidth = 1.5;
ctx.stroke();
// thrust flame when accelerating
if (keys['ArrowUp']) {
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.moveTo(-ship.r, 0);
  ctx.lineTo(-ship.r - 8, -4);
  ctx.lineTo(-ship.r - 8, 4);
  ctx.closePath();
  ctx.fill();
}
ctx.restore();

